import 'package:equatable/equatable.dart';
class SectionEntity extends Equatable { const SectionEntity({required this.id,required this.classId,required this.name,required this.isActive,required this.createdAt,required this.updatedAt}); final String id,classId,name; final bool isActive; final DateTime createdAt,updatedAt; SectionEntity copyWith({String? id,String? classId,String? name,bool? isActive,DateTime? createdAt,DateTime? updatedAt})=>SectionEntity(id:id??this.id,classId:classId??this.classId,name:name??this.name,isActive:isActive??this.isActive,createdAt:createdAt??this.createdAt,updatedAt:updatedAt??this.updatedAt); @override List<Object?> get props=>[id,classId,name,isActive,createdAt,updatedAt]; }
